void vibe_program_set_heart_bpm(uint8_t bpm) {
  bpm = bpm < 40 ? 40 : (bpm > 90 ? 90 : bpm);
  s_lab_heart[3].ms = (uint16_t)(60000 / bpm - 60 - 140 - 45);
}

